    "guide_compress_rel1_d": "Reduce el tamaño sin pérdida visible de calidad.",
    "guide_compress_rel1_t": "Compresor de imágenes",
    "guide_compress_rel2_d": "Convierte entre PNG, JPEG y WebP.",
